#include "linalg_lapack.hpp"
namespace penta::linalg {
void denseLinear(const penta_numeric_host_v1* host,const penta_linalg_request_v1& r,penta_linalg_result_v1& result){
    realMatrix(r.a);const auto& a=r.a;const auto m=static_cast<lapack_int>(a.rows),n=static_cast<lapack_int>(a.columns),k=std::min(m,n);
    const bool valueOnly=r.operation==PENTA_LA_DETERMINANT_VALUE||r.operation==PENTA_LA_CHOLESKY_FACTOR;
    const bool reuseSvd=r.operation==PENTA_LA_SOLVE&&r.method==PENTA_LA_METHOD_SVD&&a.rows&&a.columns&&r.b.columns;
    if(!valueOnly&&!reuseSvd)condition(a,r,result);
    cancelled(host);auto factor=copyReal(a);
    if(r.operation==PENTA_LA_DETERMINANT||r.operation==PENTA_LA_DETERMINANT_VALUE){require(m==n,"det requires a square real matrix; use det(leftop(A)) or det(rightop(A)) for Pentarnion operators.");if(!n){result.scalar=1;result.converged=1;return;}std::vector<lapack_int> piv(n);const auto status=LAPACKE_dgetrf(LAPACK_ROW_MAJOR,m,n,factor.data(),n,piv.data());if(status<0)lapackStatus(status,"LU determinant");long double value=1;for(lapack_int i=0;i<n;++i){value*=factor[static_cast<size_t>(i)*n+i];if(piv[i]!=i+1)value=-value;}result.scalar=finite(static_cast<double>(value));result.converged=1;return;}
    if(r.operation==PENTA_LA_INVERSE){guardedSquare(a,r,result);outputValid(result.output[0],a.rows,a.columns);if(!n){result.converged=1;return;}std::vector<lapack_int> piv(n);lapackStatus(LAPACKE_dgetrf(LAPACK_ROW_MAJOR,n,n,factor.data(),n,piv.data()),"LU inverse factorization");lapackStatus(LAPACKE_dgetri(LAPACK_ROW_MAJOR,n,factor.data(),n,piv.data()),"LU inverse");
        std::vector<double> identity(static_cast<size_t>(n)*n,0);for(lapack_int i=0;i<n;++i)identity[static_cast<size_t>(i)*n+i]=1;const penta_linalg_matrix_v1 b{a.rows,a.columns,a.count,1,0,identity.data()};residual(a,b,factor,result);if(result.relative_residual>r.residual_tolerance)throw Error(PENTA_NUMERIC_DOMAIN,"Inverse failed its backward-residual check.");copyFinite(factor,result.output[0]);result.converged=1;return;}
    if(r.operation==PENTA_LA_LU){outputValid(result.output[0],a.rows,k);outputValid(result.output[1],k,a.columns);outputValid(result.output[2],a.rows,a.rows);std::vector<lapack_int> piv(k);if(k){const auto status=LAPACKE_dgetrf(LAPACK_ROW_MAJOR,m,n,factor.data(),n,piv.data());if(status<0)lapackStatus(status,"LU");}std::vector<double> l(static_cast<size_t>(m)*k),u(static_cast<size_t>(k)*n),p(static_cast<size_t>(m)*m);for(lapack_int i=0;i<m;++i){p[static_cast<size_t>(i)*m+i]=1;for(lapack_int j=0;j<k;++j)l[static_cast<size_t>(i)*k+j]=i==j?1:i>j?factor[static_cast<size_t>(i)*n+j]:0;}for(lapack_int i=0;i<k;++i){if(piv[i]!=i+1)for(lapack_int j=0;j<m;++j)std::swap(p[static_cast<size_t>(i)*m+j],p[static_cast<size_t>(piv[i]-1)*m+j]);for(lapack_int j=i;j<n;++j)u[static_cast<size_t>(i)*n+j]=factor[static_cast<size_t>(i)*n+j];}copyFinite(l,result.output[0]);copyFinite(u,result.output[1]);copyFinite(p,result.output[2]);result.converged=1;return;}
    if(r.operation==PENTA_LA_QR){outputValid(result.output[0],a.rows,k);outputValid(result.output[1],k,a.columns);outputValid(result.output[2],a.columns,a.columns);std::vector<lapack_int> piv(n,0);std::vector<double> tau(k);if(k)lapackStatus(LAPACKE_dgeqp3(LAPACK_ROW_MAJOR,m,n,factor.data(),n,piv.data(),tau.data()),"Pivoted QR");std::vector<double> q(static_cast<size_t>(m)*k),upper(static_cast<size_t>(k)*n),p(static_cast<size_t>(n)*n);for(lapack_int i=0;i<m;++i)for(lapack_int j=0;j<k;++j)q[static_cast<size_t>(i)*k+j]=factor[static_cast<size_t>(i)*n+j];for(lapack_int i=0;i<k;++i)for(lapack_int j=i;j<n;++j)upper[static_cast<size_t>(i)*n+j]=factor[static_cast<size_t>(i)*n+j];for(lapack_int j=0;j<n;++j)p[static_cast<size_t>(k?piv[j]-1:j)*n+j]=1;if(k)lapackStatus(LAPACKE_dorgqr(LAPACK_ROW_MAJOR,m,k,k,q.data(),k,tau.data()),"QR orthogonal factor");copyFinite(q,result.output[0]);copyFinite(upper,result.output[1]);copyFinite(p,result.output[2]);result.converged=1;return;}
    if(r.operation==PENTA_LA_CHOLESKY||r.operation==PENTA_LA_CHOLESKY_FACTOR){symmetric(a);outputValid(result.output[0],a.rows,a.columns);if(n)lapackStatus(LAPACKE_dpotrf(LAPACK_ROW_MAJOR,'L',n,factor.data(),n),"Cholesky");for(lapack_int i=0;i<n;++i)for(lapack_int j=i+1;j<n;++j)factor[static_cast<size_t>(i)*n+j]=0;copyFinite(factor,result.output[0]);result.converged=1;return;}
    require(r.operation==PENTA_LA_SOLVE,"Unknown dense factorization operation.");realMatrix(r.b);require(r.b.rows==a.rows,"A and B must have matching row counts.");const auto rhs=static_cast<lapack_int>(r.b.columns);outputValid(result.output[0],a.columns,r.b.columns);
    if(!n||!rhs){std::vector<double> x(static_cast<size_t>(n)*rhs);residual(a,r.b,x,result);copyFinite(x,result.output[0]);result.converged=result.relative_residual<=r.residual_tolerance;return;}
    std::vector<double> b(static_cast<size_t>(std::max(m,n))*rhs,0);for(lapack_int i=0;i<m;++i)for(lapack_int j=0;j<rhs;++j)b[static_cast<size_t>(i)*rhs+j]=r.b.values[static_cast<size_t>(i)*rhs+j];
    if(r.method==PENTA_LA_METHOD_LU){guardedSquare(a,r,result);std::vector<lapack_int> piv(n);lapackStatus(LAPACKE_dgesv(LAPACK_ROW_MAJOR,n,rhs,factor.data(),n,piv.data(),b.data(),rhs),"LU solve");}
    else if(r.method==PENTA_LA_METHOD_CHOLESKY){guardedSquare(a,r,result);symmetric(a);lapackStatus(LAPACKE_dposv(LAPACK_ROW_MAJOR,'L',n,rhs,factor.data(),n,b.data(),rhs),"Cholesky solve");}
    else if(r.method==PENTA_LA_METHOD_QR){std::vector<lapack_int> piv(n,0);lapack_int rank=0;lapackStatus(LAPACKE_dgelsy(LAPACK_ROW_MAJOR,m,n,rhs,factor.data(),n,b.data(),rhs,piv.data(),r.rank_tolerance?r.rank_tolerance:64*std::numeric_limits<double>::epsilon()*std::max(m,n),&rank),"QR least-squares solve");result.rank=rank;}
    else if(r.method==PENTA_LA_METHOD_SVD){std::vector<double> values(k);lapack_int rank=0;lapackStatus(LAPACKE_dgelsd(LAPACK_ROW_MAJOR,m,n,rhs,factor.data(),n,b.data(),rhs,values.data(),r.rank_tolerance?r.rank_tolerance:64*std::numeric_limits<double>::epsilon()*std::max(m,n),&rank),"SVD least-squares solve");conditionFromSingular(values,a,r,result);result.rank=rank;}
    else require(false,"Unknown real linear solve method.");
    b.resize(static_cast<size_t>(n)*rhs);residual(a,r.b,b,result);result.converged=result.relative_residual<=r.residual_tolerance;copyFinite(b,result.output[0]);cancelled(host);
}
}
